head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > M > reform]<br/>DataList 모듈의 원본(Origin) 데이터가 제거되고 현재 데이터를 새로운 원본(Origin) 데이터로 재설정합니다",
    "validation" : [
        "reform() 메소드로 원본(Origin) 데이터가 재설정되면 제거(Remove)된 Row 의 정보 등이 초기화됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    // target 생성
    $c.gcm.createBasicDataList();

    // gridView 생성
    $c.gcm.createBasicGridView('dataList="data:target1" rowStatusVisible="true"', '', 'gridView1');
}   



scwin.btn_insertRow_onclick = function (e) {
    let insertIndex = target1.insertRow();
    target1.setRowData(insertIndex,["insert1","insert2","insert3","insert4"],true);

    insertIndex = target1.insertRow();
    target1.setRowData(insertIndex,["insert5","insert6","insert7","insert8"],true);

    target1.deleteRow(insertIndex);
};



scwin.btn_removeRow_onclick = function (e) {
    target1.removeRow(3);

    scwin.btn_getDeletedArray_onclick();
}



scwin.btn_reform_onclick = function (e) {
    target1.reform();    

    scwin.btn_getDeletedArray_onclick();
};



scwin.btn_getDeletedArray_onclick = function (e) {
    let rtn = target1.getDeletedArray();

    wf_body_bottom.getObj("scwin").setReturnValue("remove 정보: " + rtn.data);
};
